theme.css:
/* ==== INTERFACE ====
   token  --bg #f3f5f8            页面背景｜页面底色，清爽工程蓝灰偏冷中性底
   token  --text #1a222d          主文本｜标题、正文成句，高对比度工程深蓝灰
   token  --muted #6b7788         次级文本与结构线｜说明文字、轴线、边框（与bg对比≥4.5:1）
   token  --surface #ffffff       面板表面｜卡片背景、仪器白板、图表容器
   token  --pos #1d63b8           正类/权重增大/+1｜正样本点、权重提升、聚焦状态
   token  --neg #c2410c           负类/权重减小/-1｜负样本点、分类错误高亮、惩罚标记
   token  --model #0f766e         弱分类器/决策桩切分面｜弱分类器边界、阈值线、基模型标识
   token  --ensemble #4338ca      强分类器/集成加权结果｜最终集成边界、投票聚合标识
   token  --focus #1d63b8         键盘焦点与激活边框｜交互控件外框、可操作组件焦点态
   token  --fs-h1 34px            页面一级标题
   token  --fs-h2 22px            区块二级标题/阶段标题
   token  --fs-lead 19px          导语与核心提炼
   token  --fs-body 18px          正文成句
   token  --fs-sec 16px           次级说明与参数成句
   token  --fs-label 15px         控件与图例标签
   token  --fs-tick 13px          纯数字刻度与代码次注
   版心   1488×844                #stage 已含 padding: 28px 56px
   版式   .focus                  标题后单一主区（占满剩余垂直空间）
   版式   .split-2                左右对等/主次双栏（默认 1fr 1fr）
   版式   .split-aside            左主右辅（65% : 35%）
   组件   .panel                  带边框与白底的计算或展示卡片
   组件   .panel.q                无白色底色仅保留边距与轮廓的对照/问题卡片
   组件   .btn                    交互按钮（含 .active、:hover、:focus、:disabled 态）
   组件   .btns                   按钮组水平排列容器
   组件   .ctl                    参数控制单元（含 label 与 input[type=range]）
   组件   .big                    醒目度量数值容器
   组件   .big.sm                 小号重点数值
   组件   .big.lg                 大号终值度量
   组件   .num                    等宽对齐数字
   组件   .unit                   数值后单位/符号
   组件   .tag                    分类/阶段标签（可结合 .tag-pos, .tag-neg, .tag-model）
   组件   .legend                 图例组容器（含 .li, .sw, .sw.line）
   组件   .cvbox                  画布/图表定位视口
   组件   .quiz                   即时测验容器
   组件   .opt                    测验选项按钮（含 .selected, .correct, .incorrect）
   组件   .fb                     测验正误反馈提示条
   组件   .lead                   要点导语段落
   组件   .small                  次要提示文字
   组件   .note                   学术/直觉注解块
   ==== /INTERFACE ==== */

:root {
  --pad-x: 56px;
  --pad-y: 28px;
  --bg: #f3f5f8;
  --text: #1a222d;
  --muted: #6b7788;
  --surface: #ffffff;
  --pos: #1d63b8;
  --neg: #c2410c;
  --model: #0f766e;
  --ensemble: #4338ca;
  --focus: #1d63b8;

  --font-sans: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", "SF Mono", "Menlo", "Consolas", monospace;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: var(--fs-body);
  line-height: 1.5;
  box-sizing: border-box;
}

/* 标题与导语排版 */
.header-block {
  margin-bottom: 20px;
  flex-shrink: 0;
}

.title-h1 {
  font-size: var(--fs-h1);
  font-weight: 700;
  line-height: 1.25;
  margin: 0 0 8px 0;
  color: var(--text);
  letter-spacing: -0.01em;
}

.lead {
  font-size: var(--fs-lead);
  line-height: 1.45;
  color: var(--text);
  margin: 0;
}

.small {
  font-size: var(--fs-sec);
  line-height: 1.4;
  color: var(--muted);
}

.note {
  font-size: var(--fs-sec);
  line-height: 1.45;
  padding: 12px 16px;
  background-color: rgba(29, 99, 184, 0.06);
  border-left: 3px solid var(--pos);
  border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
  color: var(--text);
}

/* 版式布局 */
.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.split-2 {
  flex: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
  min-height: 0;
}

.split-aside {
  flex: 1;
  display: grid;
  grid-template-columns: 1.85fr 1fr;
  gap: 28px;
  min-height: 0;
}

/* 面板卡片 */
.panel {
  background-color: var(--surface);
  border: 1px solid var(--muted);
  border-radius: var(--radius-md);
  padding: 20px;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
}

.panel.q {
  background-color: transparent;
  border: 1px dashed var(--muted);
}

.panel-title {
  font-size: var(--fs-h2);
  font-weight: 600;
  margin: 0 0 14px 0;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* 数值展示 */
.big {
  font-size: 28px;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--text);
  font-variant-numeric: tabular-nums;
  line-height: 1.1;
}

.big.sm {
  font-size: 20px;
}

.big.lg {
  font-size: 40px;
}

.num {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
}

.unit {
  font-size: var(--fs-sec);
  font-weight: 400;
  color: var(--muted);
  margin-left: 4px;
}

/* 按钮与交互控件 */
.btns {
  display: flex;
  gap: 12px;
  align-items: center;
}

.btn {
  font-family: var(--font-sans);
  font-size: var(--fs-label);
  font-weight: 500;
  padding: 8px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--muted);
  background-color: var(--surface);
  color: var(--text);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.15s ease, background-color 0.15s ease;
}

.btn:hover:not(:disabled) {
  border-color: var(--focus);
  background-color: rgba(29, 99, 184, 0.05);
}

.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn.active {
  background-color: var(--pos);
  border-color: var(--pos);
  color: #ffffff;
}

.btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.ctl {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.ctl label {
  font-size: var(--fs-label);
  font-weight: 500;
  color: var(--text);
  display: flex;
  justify-content: space-between;
}

.ctl input[type="range"] {
  width: 100%;
  accent-color: var(--pos);
  cursor: pointer;
}

/* 标签与图例 */
.tag {
  display: inline-flex;
  align-items: center;
  font-size: var(--fs-tick);
  font-weight: 600;
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  background-color: rgba(107, 119, 136, 0.15);
  color: var(--text);
}

.tag-pos {
  background-color: rgba(29, 99, 184, 0.15);
  color: var(--pos);
}

.tag-neg {
  background-color: rgba(194, 65, 12, 0.15);
  color: var(--neg);
}

.tag-model {
  background-color: rgba(15, 118, 110, 0.15);
  color: var(--model);
}

.legend {
  display: flex;
  gap: 16px;
  align-items: center;
  flex-wrap: wrap;
}

.legend .li {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--fs-label);
  color: var(--text);
}

.legend .sw {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  display: inline-block;
}

.legend .sw.line {
  width: 18px;
  height: 3px;
  border-radius: 2px;
}

/* 容器视口 */
.cvbox {
  flex: 1;
  position: relative;
  border: 1px solid var(--muted);
  border-radius: var(--radius-md);
  background-color: #ffffff;
  overflow: hidden;
  min-height: 0;
}

/* 测验与问答 */
.quiz {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.opt {
  font-family: var(--font-sans);
  font-size: var(--fs-sec);
  text-align: left;
  padding: 12px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--muted);
  background-color: var(--surface);
  color: var(--text);
  cursor: pointer;
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.opt:hover:not(:disabled) {
  border-color: var(--focus);
}

.opt:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.opt.selected {
  border-color: var(--focus);
  background-color: rgba(29, 99, 184, 0.08);
}

.opt.correct {
  border-color: var(--pos);
  background-color: rgba(29, 99, 184, 0.12);
  font-weight: 600;
}

.opt.incorrect {
  border-color: var(--neg);
  background-color: rgba(194, 65, 12, 0.12);
}

.fb {
  font-size: var(--fs-sec);
  padding: 10px 14px;
  border-radius: var(--radius-sm);
  margin-top: 8px;
  line-height: 1.45;
}

.fb.ok {
  background-color: rgba(29, 99, 184, 0.1);
  color: var(--pos);
}

.fb.err {
  background-color: rgba(194, 65, 12, 0.1);
  color: var(--neg);
}

/* SVG 组件规范适配 */
svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
